/*
 * 文件作用：提供 ROS 2 节点消息回调；由包内可执行程序启动。
 * 输入/输出：见 create_subscription/create_publisher 的消息及话题声明。
 * 运行模式：ROS 2；位置单位为米，时间为秒；依赖 rclcpp 和对应消息包。
 */
#include <chrono>
#include <array>
#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/joy.hpp>
#include <std_msgs/msg/empty.hpp>
#include <quadrotor_msgs/msg/position_command.hpp>
class Manual:public rclcpp::Node{public:Manual():Node("manual_take_over"){stop_=create_publisher<std_msgs::msg::Empty>("/mandatory_stop_to_planner",10);out_=create_publisher<quadrotor_msgs::msg::PositionCommand>("/position_cmd",10);joy_=create_subscription<sensor_msgs::msg::Joy>("/joystick_from_bridge",10,[this](sensor_msgs::msg::Joy::SharedPtr m){joy=*m;have_joy=true;last_joy=now();if(m->buttons.size()>3&&(m->buttons[0]||m->buttons[1]||m->buttons[2]||m->buttons[3])){stopped=true;stop_->publish(std_msgs::msg::Empty());}if(stopped&&planner_stop){auto t=now();double dt=last_cmd.nanoseconds()? (t-last_cmd).seconds():0;last_cmd=t;pos[0]+=axis(4)*.2*dt;pos[1]+=axis(3)*.2*dt;pos[2]+=axis(1)*.2*dt;pos[3]+=axis(0)*.2*dt;quadrotor_msgs::msg::PositionCommand c;c.header.stamp=t;c.header.frame_id="manual_take_over";c.position.x=pos[0];c.position.y=pos[1];c.position.z=pos[2];c.yaw=pos[3];c.velocity.x=axis(4)*.2;c.velocity.y=axis(3)*.2;c.velocity.z=axis(1)*.2;out_->publish(c);}});cmd_=create_subscription<quadrotor_msgs::msg::PositionCommand>("/position_cmd",100,[this](quadrotor_msgs::msg::PositionCommand::SharedPtr m){if(m->header.frame_id!="manual_take_over"){last_planner=now();have_planner=true;}pos={m->position.x,m->position.y,m->position.z,m->yaw};});timer_=create_wall_timer(std::chrono::milliseconds(400),[this]{planner_stop=have_planner&&(now()-last_planner).seconds()>1.;});}private:double axis(size_t i){return i<joy.axes.size()?joy.axes[i]:0.;}rclcpp::Time now(){return get_clock()->now();}sensor_msgs::msg::Joy joy;std::array<double,4>pos{0,0,0,0};bool have_joy=false,have_planner=false,stopped=false,planner_stop=false;rclcpp::Time last_joy,last_planner,last_cmd;rclcpp::Subscription<sensor_msgs::msg::Joy>::SharedPtr joy_;rclcpp::Subscription<quadrotor_msgs::msg::PositionCommand>::SharedPtr cmd_;rclcpp::Publisher<std_msgs::msg::Empty>::SharedPtr stop_;rclcpp::Publisher<quadrotor_msgs::msg::PositionCommand>::SharedPtr out_;rclcpp::TimerBase::SharedPtr timer_;};int main(int c,char**v){rclcpp::init(c,v);rclcpp::spin(std::make_shared<Manual>());rclcpp::shutdown();}
